        {
            // Props can arrive shortly after room enter — re-apply once after a short wait.
            const float totalWait = 1.5f;
            const float step = 0.25f;
            float waited = 0f;

            while (waited < totalWait)
            {
                yield return new WaitForSeconds(step);
                waited += step;

